plugins {
    id("com.android.library")
    id("org.jetbrains.kotlin.android")
    `maven-publish`
}

group = "ai.masko"
version = "0.1.0"

val media3 = "1.6.1"
val jna = "5.17.0"

android {
    namespace = "ai.masko.player"
    compileSdk = 35

    defaultConfig {
        minSdk = 24
        testInstrumentationRunner = "androidx.test.runner.AndroidJUnitRunner"
        consumerProguardFiles("consumer-rules.pro")
    }

    sourceSets {
        // The Kotlin MaskoEngine bindings, generated by scripts/build-android.sh.
        getByName("main").java.srcDir("src/main/generated")
    }

    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }

    testOptions {
        targetSdk = 35
        unitTests.all {
            it.systemProperty(
                "masko.fixtures",
                (project.findProperty("masko.fixtures") as String?) ?: rootProject.file("../spec/fixtures").absolutePath,
            )
            it.testLogging {
                events("passed", "failed", "skipped")
                showStandardStreams = false
            }
        }
    }

    lint {
        targetSdk = 35
    }

    publishing {
        singleVariant("release") {
            withSourcesJar()
        }
    }
}

kotlin {
    jvmToolchain(17)
}

dependencies {
    implementation("androidx.media3:media3-exoplayer:$media3")
    implementation("androidx.media3:media3-datasource:$media3")
    implementation("androidx.media3:media3-database:$media3")
    // JNA with its Android native parts; the generated bindings call the engine through it.
    implementation("net.java.dev.jna:jna:$jna@aar")
    // @RequiresApi in the generated bindings.
    implementation("androidx.annotation:annotation:1.9.1")

    // JVM tests load the host engine library (src/test/resources) through the desktop JNA.
    testImplementation("net.java.dev.jna:jna:$jna")
    testImplementation("junit:junit:4.13.2")
    // android.jar has only stubs of org.json.
    testImplementation("org.json:json:20240303")

    androidTestImplementation("androidx.test:runner:1.6.2")
    androidTestImplementation("androidx.test:core:1.6.1")
    androidTestImplementation("androidx.test.ext:junit:1.2.1")
}

// The engine is built outside Gradle; say so clearly instead of failing on a missing class.
val checkEngine by tasks.registering {
    val generated = file("src/main/generated/ai/masko/player/engine/masko_player_ffi.kt")
    val abis = listOf("arm64-v8a", "armeabi-v7a", "x86_64").map { file("src/main/jniLibs/$it/libmasko_player_ffi.so") }
    doLast {
        val missing = (listOf(generated) + abis).filterNot { it.exists() }
        if (missing.isNotEmpty()) {
            throw GradleException(
                "Missing engine files (run scripts/build-android.sh from the repository root):\n" +
                    missing.joinToString("\n") { "  $it" }
            )
        }
    }
}
tasks.named("preBuild") { dependsOn(checkEngine) }

publishing {
    publications {
        register<MavenPublication>("release") {
            groupId = "ai.masko"
            artifactId = "player"
            version = project.version.toString()
            afterEvaluate { from(components["release"]) }
        }
    }
    repositories {
        // `./gradlew :player:publishReleasePublicationToLocalRepository` writes build/repo.
        maven {
            name = "local"
            url = uri(layout.buildDirectory.dir("repo"))
        }
    }
}
